def calculate_sums(a, b, c, d):
    sum1 = a**2 + b**2
    sum2 = c**2 + d**2
    return sum1, sum2

def find_squares(n):
    solutions = []
    for e in range(int(n**0.5) + 1):
        f_squared = n - e**2
        if f_squared >= 0:
            f = int(f_squared**0.5)
            if f_squared == f**2:
                solutions.append([e, f])
    return solutions

def sort_solutions(solutions):
    return sorted(solutions, key=lambda x: x[0])

def prod2sum(a, b, c, d):
    sum1, sum2 = calculate_sums(a, b, c, d)
    n = sum1 * sum2
    solutions = find_squares(n)
    return sort_solutions(solutions)

