                corners[i] + width + height in corners) for i in range(len(corners)))

def count_squares(lines):
    corners = []
    for line in lines:
        corners.extend(find_corners(line))

    squares = 0
    for i in range(len(corners)):
        for j in range(i + 1, len(corners)):
            for k in range(j + 1, len(corners)):
                for l in range(k + 1, len(corners)):
                    x1, y1 = corners[i] // len(lines[0]), corners[i] % len(lines[0])
                    x2, y2 = corners[j] // len(lines[0]), corners[j] % len(lines[0])
                    x3, y3 = corners[k] // len(lines[0]), corners[k] % len(lines[0])
                    x4, y4 = corners[l] // len(lines[0]), corners[l] % len(lines[0])

                    width = abs(x2 - x1)
                    height = abs(y2 - y1)

                    if width == height and is_valid_square([corners[i], corners[j], corners[k], corners[l]], width, height):
