def calculate_next_element(num):
    if num < 10:
        return num + num
    else:
        non_zero_digits = [int(digit) for digit in str(num) if digit != '0']
        product_of_digits = 1
        for digit in non_zero_digits:
            product_of_digits *= digit
        return num + product_of_digits

def generate_series(seed):
    series = [seed]
    while True:
        next_element = calculate_next_element(series[-1])
        if next_element in series:
            break
        series.append(next_element)
    return series

def find_convergence_length(seed):
    base_series = generate_series(1)
    test_series = generate_series(seed)
    for i, num in enumerate(test_series):
        if num in base_series:
            return i
    return len(test_series)

