def generate_look_and_say_number(n):
    if n == 1:
        return "1"
    prev_number = "1"
    for _ in range(1, n):
        next_number = ""
        i = 0
        while i < len(prev_number):
            count = 1
            while i + 1 < len(prev_number) and prev_number[i] == prev_number[i + 1]:
                i += 1
                count += 1
            next_number += str(count) + prev_number[i]
            i += 1
        prev_number = next_number
    return prev_number

