    return max(0, min(2.375, a))

def calculate_b(yards, attempts):
    b = ((yards / attempts) - 3) * 0.25
    return max(0, min(2.375, b))

def calculate_c(touchdowns, attempts):
    c = (touchdowns / attempts) * 20
    return max(0, min(2.375, c))

def calculate_d(interceptions, attempts):
    d = 2.375 - ((interceptions / attempts) * 25)
    return max(0, min(2.375, d))

def passer_rating(att, yds, comp, td, ints):
