def move_to_key(current_key, target_key, keyboard_layout):
    current_row, current_col = keyboard_layout.index(current_key) // 10, keyboard_layout.index(current_key) % 10
    target_row, target_col = keyboard_layout.index(target_key) // 10, keyboard_layout.index(target_key) % 10
    return abs(current_row - target_row) + abs(current_col - target_col)

def calculate_presses(word, keyboard_layout):
    total_presses = 0
    current_key = 'a'
    for char in word:
        if char.isalpha():
            target_key = char.lower() if char.islower() else char.upper()
            total_presses += move_to_key(current_key, target_key, keyboard_layout)
            total_presses += 1  # OK button press
            current_key = target_key
        elif char == ' ':
            total_presses += move_to_key(current_key, 'SP', keyboard_layout)
            total_presses += 1  # OK button press
            current_key = 'SP'
    return total_presses

