def count_shoes_by_size(shoes):
    left_count = {}
    right_count = {}

    for shoe in shoes:
        shoe_type, shoe_size = shoe
        if shoe_type == 0:
            left_count[shoe_size] = left_count.get(shoe_size, 0) + 1
