def is_repeated_substring(s):
    n = len(s)
    for i in range(1, n // 2 + 1):
        if n % i == 0:
            substring = s[:i]
            repeated = substring * (n // i)
            if repeated == s:
                return True
    return False

def prime_string(s):
    return not is_repeated_substring(s)

def break_camel_case(s):
    """Helper function to break camel case by inserting spaces."""
    return ''.join([' ' + char if char.isupper() else char for char in s])

