def reverse_array(array):
    return array[::-1]

def convert_to_int(array):
    return int(''.join(map(str, array)))

def convert_to_array(number):
    return list(map(int, str(number)))

def sum_arrays(array1, array2):
    reversed_array1 = reverse_array(array1)
    reversed_array2 = reverse_array(array2)

    number1 = convert_to_int(reversed_array1)
    number2 = convert_to_int(reversed_array2)

    sum_number = number1 + number2

    return reverse_array(convert_to_array(sum_number))

def is_black_key(key_number):
    """Determine if a key number corresponds to a black key."""
    # Black keys are at positions 1, 3, 5, ..., 87 (1-based index)
    return (key_number - 1) % 12 in {1, 3, 5, 7, 9, 11}

def is_white_key(key_number):
    """Determine if a key number corresponds to a white key."""
    # White keys are at positions 2, 4, 6, ..., 88 (1-based index)
    return (key_number - 1) % 12 in {0, 2, 4, 5, 7, 8, 10, 11}

def black_or_white_key(key_press_count):
    """Determine if the key at the given key press count is black or white."""
    # Normalize the key press count to be within the range of one full cycle (88 keys)
    normalized_key = key_press_count % 88
    # If the normalized key is 0, it corresponds to the 88th key, which is white
    if normalized_key == 0:
        return "white"
    # Otherwise, use the helper functions to determine the color
    return "black" if is_black_key(normalized_key) else "white"

def calculate_points(lines_cleared, level):
    points_per_line = [40, 100, 300, 1200]
    if lines_cleared < 4:
        return lines_cleared * points_per_line[lines_cleared]
    else:
        return 1200 + (lines_cleared - 4) * 500 * (level + 1)

def update_level(total_lines_cleared):
    return total_lines_cleared // 10

def calculate_total_score(arr):
    total_score = 0
    total_lines_cleared = 0
    current_level = 0

    for lines in arr:
        if lines > 0:
            points = calculate_points(lines, current_level)
            total_score += points
            total_lines_cleared += lines
            current_level = update_level(total_lines_cleared)

    return total_score

def get_score(arr) -> int:
    return calculate_total_score(arr)

def count_char_frequency(s):
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    return freq

def calculate_min_replacements(s, t):
    freq_s = count_char_frequency(s)
    freq_t = count_char_frequency(t)

    replacements = 0
    for char, count in freq_s.items():
        if char in freq_t:
            if count > freq_t[char]:
                replacements += count - freq_t[char]
        else:
            replacements += count

    return replacements

def create_anagram(s, t):
    return calculate_min_replacements(s, t)
